class Solution {
    public int findGCD(int[] nums){
        int minimum=Arrays.stream(nums).min().getAsInt(),maximum=Arrays.stream(nums).max().getAsInt();
        while(minimum!=0){
            int remainder=maximum%minimum;
            maximum=minimum;
            minimum=remainder;
        }
        return maximum;
    }
}

code.kotlin:
class Solution {
    fun findGCD(nums:IntArray):Int{
        var minimum=nums.minOrNull()!!;
        var maximum=nums.maxOrNull()!!;
        while(minimum!=0){
            val remainder=maximum%minimum;
            maximum=minimum;
            minimum=remainder
        };
        return maximum
    }
}

